Ltac norm_sub :=
  repeat match goal with
  | |- context [Z.sub (bv_unsigned ?x) ?c] => is_Zlit c; let v := eval vm_compute in (- c)%Z in
        replace (Z.sub (bv_unsigned x) c) with (Z.add (bv_unsigned x) v) by lia
  end.
Ltac zs := zstep; norm_sub.

